      source  = "hashicorp/aws"
      version = "~> 5.31"
    }
  }

  backend "s3" {
    bucket = "REPLACE_WITH_YOUR_STATE_BUCKET"
    key    = "envs/prod/terraform.tfstate"
    region = "us-east-1"
  }
}

