```hcl
# main.tf

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.31"
    }
  }

  backend "s3" {
    key    = "envs/prod/terraform.tfstate"
    region = "us-east-1"
